struct Base {
    virtual ~Base() = default;
};
struct Derived : Base {};

Base* ptr = new Derived;

// Static type check (Compile time)
const std::type_info& t_static = typeid(Base);

// Dynamic type check (Requires VTable lookup via typeid(*ptr))
const std::type_info& t_dynamic = typeid(*ptr);

// Runtime comparison
bool check = (t_dynamic == typeid(Derived));

// Standard library features
const char* type_name = t_dynamic.name();
size_t type_hash = t_dynamic.hash_code();

// Ordering (implementation specific)
bool relative = t_static.before(t_dynamic);
